function createSkillFromDialog(){
 const name=document.querySelector('#new-skill-name').value.trim(),level=Number(document.querySelector('#new-skill-level').value),category=document.querySelector('#new-skill-category').value,attribute=document.querySelector('#new-skill-attribute').value,formula=document.querySelector('#new-skill-formula').value;
 let skill=[name,level,category,attribute,formula,document.querySelector('#new-skill-description').value],error=!name?'Введите название навыка.':!Number.isInteger(level)||level<1?'Уровень должен быть целым числом от 1.':skillResult(skill).error;
 if(error){document.querySelector('#new-skill-error').textContent=error;return false;}
 if(!spendPoints('freeSkills',learnSkillCost(level))){document.querySelector('#new-skill-error').textContent='Недостаточно очков навыков. Нужно: '+learnSkillCost(level)+'. Свободно: '+state.info.freeSkills;return false;}state.skills.push(skill);skillCreateOpen=false;filter='Все';return true;
}
function renderDamageDialog(){
 if(!damageOpen)return '';
 return `<dialog id="damage-dialog" class="formula-dialog" aria-labelledby="damage-heading"><div class="toolbar"><h2 id="damage-heading">Попадание: ${names[zone]}</h2><button data-closedamage aria-label="Закрыть ввод урона">×</button></div><p class="muted">Урон зоны сейчас: ${state.zones[zone].damage} · HP: ${state.info.hp} / ${state.info.maxhp}</p><label>Урон после брони<input id="hit-damage" aria-label="Урон попадания" type="number" min="1" step="1" placeholder="0" autofocus data-hit-preview></label><small>Будет добавлен к урону этой зоны и вычтен из HP. Броня уже должна быть учтена.</small><label class="check-row"><input id="hit-heavy-regen" type="checkbox" ${state.info.heavyRegen?'checked':''} data-hit-preview>Регенерация тяжёлых повреждений</label><div id="hit-preview">${renderInjury(zone,state.zones[zone].damage)}</div><div id="hit-error" class="formula-error" role="status"></div><div class="dialog-actions"><button data-closedamage>Отмена</button><button data-applyhit>Нанести урон</button></div></dialog>`;
}
function updateHitPreview(){const value=Number(document.querySelector('#hit-damage').value);document.querySelector('#hit-preview').innerHTML=renderInjury(zone,state.zones[zone].damage+(Number.isFinite(value)?Math.max(0,value):0),document.querySelector('#hit-heavy-regen').checked);}
function applyHit(){
 const amount=Number(document.querySelector('#hit-damage').value);
 if(!Number.isSafeInteger(amount)||amount<=0){document.querySelector('#hit-error').textContent='Введите положительное целое число урона.';return false;}
 if(!Number.isSafeInteger(state.zones[zone].damage+amount)){document.querySelector('#hit-error').textContent='Слишком большое значение урона.';return false;}
 state.hitHistory??=[];const hpBefore=state.info.hp,damageBefore=state.zones[zone].damage,regenBefore=!!state.info.heavyRegen;
 state.info.heavyRegen=document.querySelector('#hit-heavy-regen').checked;
 state.zones[zone].damage+=amount;state.info.hp=Math.max(0,state.info.hp-amount);
 state.hitHistory.push({zone,amount,hpBefore,damageBefore,hpAfter:state.info.hp,regenBefore});damageOpen=false;return true;
}
function undoHit(){
 const hit=state.hitHistory?.pop();if(!hit)return;
 zone=hit.zone;state.zones[zone].damage=Math.max(0,state.zones[zone].damage-hit.amount);state.info.hp=Math.max(0,Math.min(state.info.maxhp,state.info.hp+(hit.hpBefore-hit.hpAfter)));state.info.heavyRegen=hit.regenBefore;
}
function renderZoneStatus(){
 return `<div class="zonebox"><h3>${names[zone]}</h3><div class="fields"><label>Броня<input type="number" min="0" data-z="armor" value="${state.zones[zone].armor}"></label><label>Урон зоны<input aria-label="Накопленный урон зоны" type="number" min="0" data-z="damage" value="${state.zones[zone].damage}"></label><label>Состояние<input data-z="note" value="${esc(state.zones[zone].note)}" placeholder="Без ранений"></label></div><div class="row hit-actions"><button data-openhit>+ Попадание</button>${state.hitHistory?.length?'<button data-undohit>↶ Отменить попадание</button>':''}</div><small>Числа на фигуре — накопленный урон зоны. Изменение корректирует HP; пороги считаются от максимальных HP.</small><h3>Предлагаемая травма</h3>${renderInjury(zone,state.zones[zone].damage)}${injuryFor(zone,state.zones[zone].damage).tier>0?'<button class="adopt-injury" data-adoptinjury>Записать в состояние зоны</button>':''}</div>`;
}

function migrateCharacter(data){
 migrateSkills(data);data.stats.forEach(s=>{s[3]=Math.max(0,Number(s[3])||0)});
 data.items=data.items.map(item=>{
  if(Array.isArray(item)){let category=item[2];if(category==='Снаряжение')category=/ПНВ|амулет|кольцо/i.test(item[0])?'Аксессуары':/щит/i.test(item[0])?'Броня':'Прочее';return {name:item[0],qty:item[1],category:['Оружие','Броня','Аксессуары','Прочее'].includes(category)?category:'Прочее',notes:item[3],equipped:false,weight:0,value:0,bonuses:{},details:{}};}
  return {...item,bonuses:item.bonuses||{},details:item.details||{},equipped:!!item.equipped};
 });
 for(const item of data.items){if(item.legacyParsed)continue;const notes=item.notes||'';
  for(const match of notes.matchAll(/\+(\d+)\s*(STR|DEX|CON|RTC|ACC|INT|LCK|CHA)\b/gi)){const code=match[2].toUpperCase();if(item.bonuses[code]===undefined)item.bonuses[code]=Number(match[1]);}
  const lookup=(re)=>notes.match(re)?.[1];
  if(item.category==='Оружие'){for(const [key,re] of [['damage',/урон\s+([^;]+)/i],['armorPen',/бронебойность\s+([^;]+)/i],['range',/дальность\s+([^;]+)/i]])if(!item.details[key]&&lookup(re))item.details[key]=lookup(re);}
  if(item.category==='Броня'&&!item.details.protection&&lookup(/коэффициент\s+(\d+)/i))item.details.protection=lookup(/коэффициент\s+(\d+)/i);
  item.legacyParsed=true;
 }
 return data;
}
function formatStatMentions(text){return String(text).replace(/\+(\d+)\s*(STR|DEX|CON|RTC|ACC|INT|LCK|CHA)\b/gi,(_,n,code)=>code.toUpperCase()+' ('+n+')')}
function statBonus(code){const stat=state.stats.find(s=>s[1]===code);return (Number(stat?.[3])||0)+state.items.reduce((sum,item)=>sum+(item.equipped?Number(item.bonuses?.[code])||0:0),0)}
function statTotal(code){return Number(state.stats.find(s=>s[1]===code)?.[2]||0)+statBonus(code)}
function attributeOptions(selected,codes=state.stats.map(s=>s[1])){return state.stats.filter(s=>codes.includes(s[1])).map(s=>`<option value="${s[1]}" ${s[1]===selected?'selected':''}>${esc(s[0])} (${statTotal(s[1])})</option>`).join('')}
function renderStat(stat,i){const bonus=statBonus(stat[1]);return `<div class="stat"><small>${stat[1]}</small><label>${esc(stat[0])}</label><div class="stat-values"><input aria-label="${esc(stat[0])}" title="Базовое значение; итог ${statTotal(stat[1])}. Повышение на 1 стоит ${Math.max(1,Math.floor(stat[2]/10))} очк." type="number" min="0" data-stat="${i}" value="${stat[2]}">${bonus?`<span class="stat-bonus" title="Бонус от настроек и надетых предметов">(${bonus})</span>`:''}<button class="stat-gear" data-statgear="${i}" aria-label="Бонус характеристики: ${esc(stat[0])}">⚙</button></div></div>`}
function renderStatDialog(){if(statEdit<0)return '';const s=state.stats[statEdit];return `<dialog id="stat-dialog" class="formula-dialog" aria-labelledby="stat-heading"><div class="toolbar"><h2 id="stat-heading">${esc(s[0])}</h2><button data-closestat aria-label="Закрыть характеристику">×</button></div><label>Базовое значение<input id="stat-base" type="number" min="0" value="${s[2]}"></label><label>Дополнительный бонус<input id="stat-bonus" type="number" min="0" value="${s[3]||0}"></label><p class="muted">От надетых предметов: ${statBonus(s[1])-(s[3]||0)}. Итог для формул: ${statTotal(s[1])}.</p><p class="muted">Повышение стоит max(1, целая часть базового значения / 10) за каждый шаг. Уменьшение возвращает очки. Разрешён отрицательный баланс.</p><p id="stat-cost-error" class="formula-error" role="status"></p><div class="dialog-actions"><button data-closestat>Отмена</button><button data-savestat>Применить</button></div></dialog>`}
function renderCatalogDialog(){
 if(!skillCatalogOpen)return '';const entry=SKILL_CATALOG[0];return `<dialog id="catalog-dialog" class="formula-dialog" aria-labelledby="catalog-heading"><div class="toolbar"><h2 id="catalog-heading">Добавить навык</h2><button data-closecatalog aria-label="Закрыть список навыков">×</button></div><label>Навык из Sacralic<select id="catalog-select">${['Мирные','Боевые'].map(category=>`<optgroup label="${category}">${SKILL_CATALOG.filter(s=>s.category===category).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</optgroup>`).join('')}</select></label><div id="catalog-settings"></div><p class="point-cost-note">Изучение стоит 1 очко; каждый следующий шаг — текущий уровень навыка. Свободно: ${state.info.freeSkills}.</p><div id="catalog-error" class="formula-error" role="status"></div><div class="dialog-actions"><button data-customskill>Создать новый навык</button><button data-addcatalog>Добавить</button></div></dialog>`;
}
function updateCatalogSettings(){const select=document.querySelector('#catalog-select');if(!select)return;const entry=SKILL_CATALOG.find(s=>s.id===select.value);document.querySelector('#catalog-settings').innerHTML=`<p class="muted">${entry.category} · Основная характеристика${entry.attributes.length>1?' зависит от контекста':''}</p><div class="fields"><label>Уровень<input id="catalog-level" type="number" min="1" step="1" value="1"></label><label>Характеристика<select id="catalog-attribute">${attributeOptions(entry.attribute,entry.attributes)}</select></label></div>${entry.specialization?'<label>Специализация<input id="catalog-specialization" placeholder="Необязательно: например, химия"></label>':''}<label>Применяемая формула<input readonly value="${esc(entry.formula)}"></label><small>После добавления формулу можно изменить шестерёнкой.</small>${combatKey([entry.name,1,entry.category,entry.attribute,entry.formula,'',entry.id])?`<div class="catalog-combat-preview">${renderCombatInfo([entry.name,1,entry.category,entry.attribute,entry.formula,'',entry.id])}</div>`:''}`;}
function addCatalogSkill(){const entry=SKILL_CATALOG.find(s=>s.id===document.querySelector('#catalog-select').value),level=Number(document.querySelector('#catalog-level').value);if(!Number.isInteger(level)||level<1){document.querySelector('#catalog-error').textContent='Уровень должен быть целым числом от 1.';return false;}const specialization=document.querySelector('#catalog-specialization')?.value.trim();if(!spendPoints('freeSkills',learnSkillCost(level))){document.querySelector('#catalog-error').textContent='Недостаточно очков навыков. Нужно: '+learnSkillCost(level)+'. Свободно: '+state.info.freeSkills;return false;}state.skills.push([entry.name+(specialization?' — '+specialization:''),level,entry.category,document.querySelector('#catalog-attribute').value,entry.formula,'',entry.id]);skillCatalogOpen=false;filter='Все';return true;}
const inventoryCategories=['Оружие','Броня','Аксессуары','Прочее'];
